import numpy as np
from scipy.optimize import minimize

def objective(vars):
    y, z = vars
    if y <= 0 or z <= 0:
        return 0
    return - (32 * y * z * (1 + y + z)) / ((1 + y)**2 * (1 + z)**2)

# Try different starting points
max_val = 0
for y0 in [0.1, 1, 10]:
    for z0 in [0.1, 1, 10]:
        res = minimize(objective, [y0, z0], bounds=[(1e-6, None), (1e-6, None)])
        if res.success:
            max_val = max(max_val, -res.fun)

print(f"Max value found: {max_val}")

